export type Motion = (typeof MOTION)[number];

export type SceneDef = {
  type: SceneType;
  from: number;
  duration: number;
  /** Frame offset within the scene where its content is fully on screen. */
  focus: number;
  roles: Role[];
};

// Technical facts about a template. These come from code, never from tagging.
